// Copies the built single-file game into the desktop app.
const fs = require('fs'), path = require('path');
const src = path.join(__dirname, '..', 'index.html'), dst = path.join(__dirname, 'game', 'index.html');
fs.mkdirSync(path.dirname(dst), { recursive: true });
fs.copyFileSync(src, dst);
console.log('game copied:', (fs.statSync(dst).size / 1024).toFixed(0), 'KB');
// realistic bodies (generated by tools/mh-build.mjs from MakeHuman's CC0 data)
const hs = path.join(__dirname, '..', 'assets', 'humans'), hd = path.join(__dirname, 'game', 'assets', 'humans');
if (fs.existsSync(hs)) { fs.mkdirSync(hd, { recursive: true }); for (const f of fs.readdirSync(hs)) fs.copyFileSync(path.join(hs, f), path.join(hd, f)); console.log('bodies copied:', fs.readdirSync(hd).length, 'files'); }
// Malayalam voices (generated by tools/voice/make.py)
const vs = path.join(__dirname, '..', 'assets', 'voice'), vd = path.join(__dirname, 'game', 'assets', 'voice');
if (fs.existsSync(vs)) { fs.mkdirSync(vd, { recursive: true }); for (const f of fs.readdirSync(vs)) fs.copyFileSync(path.join(vs, f), path.join(vd, f)); console.log('voices copied:', fs.readdirSync(vd).length, 'files'); }
